  department hrm_platform_departments? @relation(fields: [department_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([role_id])
  @@index([department_id])
  @@index([employee_id, created_at])
  @@index([user_id, created_at])
  @@index([organization_id, created_at])
}

