  //   - format: (propertyKey targetModel constraint)
  //----
  employee hrm_platform_employees @relation(fields: [hrm_platform_employee_id], references: [id], onDelete: Cascade)
  project hrm_platform_projects? @relation(fields: [hrm_platform_project_id], references: [id], onDelete: Cascade)
