    paginationResponse.pagination.records,
    1,
  );
  TestValidator.equals(
    "pagination pages",
    paginationResponse.pagination.pages,
    1,
  );
  TestValidator.equals(
    "pagination limit",
    paginationResponse.pagination.limit,
    10,
  );
}

