    "pagination records",
    response.pagination.records,
    mockProjects.length,
  );
  TestValidator.equals("pagination pages", response.pagination.pages, 1);
  // 5. Validate data contains all projects
  TestValidator.equals(
    "data length",
    response.data.length,
    mockProjects.length,
  );
