  const timelogStart = new Date();
  timelogStart.setHours(9, 0, 0, 0);
  const timelogEnd = new Date();
  timelogEnd.setHours(17, 0, 0, 0);
  const timelog = await api.functional.hrmPlatform.member.timelogs.create(
