    await api.functional.hrmPlatform.member.time_tracking_timezones.update(
      memberConnection,
      {
        timezoneId,
        body: {
          timezone: newTimezone,
        } satisfies IHrmPlatformTimeTrackingTimezone.IUpdate,
      },
    );
  typia.assert(updatedTimezone);
