  TestValidator.predicate(
    "draft timesheet count is non-negative",
    weeklyHours.draft_timesheet_count >= 0,
  );
  TestValidator.predicate(
    "submitted timesheet count is non-negative",
    weeklyHours.submitted_timesheet_count >= 0,
  );
  TestValidator.predicate(
