        updated_at: true,
        deleted_at: true,
        timelogs: {
          select: {
            billable: true,
          },
        } satisfies Prisma.hrm_platform_timelogsFindManyArgs,
        _count: {
          select: {
            timelogs: true,
          },
        },
      },
    } satisfies Prisma.hrm_platform_projectsFindManyArgs;
  }
  export async function transform(
    input: Payload,
  ): Promise<IHrmPlatformProject.ISummary> {
